import { movies } from "../../../data/movies";
import Link from "next/link";
import { notFound } from "next/navigation";

// YouTubeのIDを抜き出す関数
const getYouTubeId = (url: string) => {
  const regExp = /^.*(youtu.be\/|v\/|u\/\w\/|embed\/|watch\?v=|&v=)([^#&?]*).*/;
  const match = url.match(regExp);
  return (match && match[2].length === 11) ? match[2] : null;
};

// TikTokのIDを抜き出す関数
const getTikTokId = (url: string) => {
  const match = url.match(/\/video\/(\d+)/) || url.match(/\/v\/(\d+)/);
  return match ? match[1] : null;
};

export default async function MovieDetailPage({ params }: { params: Promise<{ id: string }> }) {
  const { id } = await params;
  const movie = movies.find((m) => m.id === id);

  if (!movie) {
    notFound();
  }

  // ★ 埋め込みURLと、動的にコンテナのクラスを設定するための変数
  let embedUrl = "";
  let playerClass = ""; // コンテナのアスペクト比と幅を指定するクラス

  if (movie.type === 'youtube') {
    const videoId = getYouTubeId(movie.url);
    embedUrl = videoId ? `https://www.youtube.com/embed/${videoId}` : movie.url;
    // YouTubeは常に横長 (16:9)
    playerClass = "aspect-video w-full rounded-2xl"; 
  } else if (movie.type === 'tiktok') {
    const videoId = getTikTokId(movie.url);
    embedUrl = videoId ? `https://www.tiktok.com/embed/${videoId}` : movie.url;
    // ★ TikTokは常に縦長 (9:16)。パソコンでは中央配置で最大幅を制限して、巨大になりすぎないようにする。
    playerClass = "aspect-[9/16] w-full max-w-[360px] mx-auto rounded-2xl md:max-w-[400px]"; 
  }

  return (
    <div className="min-h-screen bg-[#020617] text-white p-4 md:p-8">
      <div className="max-w-4xl mx-auto">
        <Link href="/" className="text-blue-400 hover:underline mb-8 inline-block text-sm">
          ← ギャラリーに戻る
        </Link>

        {/* --- 動画プレイヤーエリア --- */}
        <div className="mb-8">
          {/* ★ 動的に設定したクラス(`${playerClass}`)を使用 */}
          <div className={`${playerClass} overflow-hidden bg-black shadow-2xl border border-white/10 active:shadow-blue-500/20 active:border-blue-500/50 transition-shadow`}>
            <iframe
              src={embedUrl}
              className="w-full h-full border-none"
              allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share"
              allowFullScreen
              // ★ TikTokの埋め込みで余計なスクロールバーが出るのを防ぐ（効果がある場合がある）
              scrolling="no" 
            />
          </div>
        </div>

        {/* 情報エリア */}
        <div className="space-y-6">
          {/* タイトルと作者情報のコンテナ */}
          <div className="flex flex-col md:flex-row md:items-end justify-between gap-4">
            <div>
              <h1 className="text-3xl font-bold mb-2">{movie.title}</h1>
              <div className="flex items-center gap-4 text-sm text-gray-400">
                <span>作者: {movie.creator}</span>
                <span className="px-2 py-0.5 bg-white/10 rounded">ツール: {movie.tool}</span>
              </div>
            </div>

            {/* 外部サイト視聴ボタン (復活させたもの) */}
            <a
              href={movie.url}
              target="_blank"
              rel="noopener noreferrer"
              className="inline-flex items-center justify-center gap-2 rounded-full bg-white/10 px-6 py-3 text-sm font-medium text-white transition-all hover:bg-white/20 border border-white/10 active:scale-95"
            >
              <span className="opacity-70">
                {movie.type === 'youtube' ? '▶' : '🎵'}
              </span>
              {movie.type === 'youtube' ? 'YouTubeで視聴する' : 'TikTokで視聴する'}
            </a>
          </div>

          {/* 作品解説 / 制作秘話 */}
          <div className="bg-white/5 p-6 rounded-xl border border-white/10 leading-relaxed text-gray-300">
            <h2 className="text-lg font-bold mb-4 text-blue-400">作品解説 / 制作秘話</h2>
            <p>{(movie as any).description || "現在、制作秘話を準備中です。この作品は最新のAI技術を用いて生成されました。"}</p>
          </div>

          {/* タグ一覧 */}
<div className="flex flex-wrap gap-2 pt-4">
  {movie.tags?.map(tag => (
    <Link 
      key={tag} 
      href={`/?tag=${encodeURIComponent(tag)}`} // トップページにタグ情報を付けて飛ばす
      className="text-xs text-blue-400 hover:text-blue-300 hover:underline transition-colors"
    >
      #{tag}
    </Link>
  ))}
</div>
        </div>
      </div>
    </div>
  );
}